#!/usr/bin/env bash
# run_p5_d_meyr_cfo_top_unit.sh
#
# P5-01A Step D Level-1 unit sim launcher.
# Invokes Vivado in batch mode to register the xfft IPs, build sim
# sources, then xsim-compile and run the meyr_cfo_top unit TB.
#
# Pre-reqs:
#   - Vivado 2022.2 installed under VIVADO_DIR (default below).
#   - vectors/bk_conj_fft512_rom.txt (generated by gen_p5_bk_conj_fft512_rom.py).
#   - vectors/p5_d/*.mem (generated by gen_p5_d_stimulus.py).
#
# Outputs:
#   vivado_xsim/logs/p5_d_{compile,elab,sim}.log
#   vivado_xsim/reports/p5_d_gate.txt
set -euo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
VIVADO_DIR="${VIVADO_DIR:-/home/zealatan/Downloads/Vivado/2022.2}"

# Locked PHASE5 target part (ZCU102). Overridable only when CI/local Vivado
# lacks ZU9 device files; the TCL records any substitution into the gate.
export XFFT_TARGET_PART="${XFFT_TARGET_PART:-xczu9eg-ffvb1156-2-e}"
echo "[p5-d] XFFT_TARGET_PART=$XFFT_TARGET_PART"

if [[ ! -x "$VIVADO_DIR/bin/vivado" ]]; then
    echo "[p5-d] ERROR: vivado not found at $VIVADO_DIR/bin/vivado" >&2
    exit 2
fi

# Regenerate vectors deterministically so the sim is reproducible.
python3 "$ROOT/scripts/gen_p5_bk_conj_fft512_rom.py"
python3 "$ROOT/scripts/check_p5_bk_conj_fft512_rom.py"
python3 "$ROOT/scripts/gen_p5_d_stimulus.py"

cd "$ROOT"
# Vivado's settings64.sh sources DocNav helpers that may be missing on
# headless installs; tolerate that one missing file without aborting.
set +e
# shellcheck disable=SC1090
source "$VIVADO_DIR/settings64.sh"
set -e
vivado -mode batch -source vivado_xsim/tcl/run_p5_d_meyr_cfo_top_unit.tcl \
    -log vivado_xsim/logs/p5_d_vivado.log \
    -journal vivado_xsim/logs/p5_d_vivado.jou
